package com.gbconnected.users.adapter.postgres;
import com.gbconnected.users.application.port.out.*; import com.gbconnected.users.application.query.*; import java.sql.*; import java.util.*; import java.util.UUID; import javax.sql.DataSource;
public final class JdbcUserAccessQueryAdapter implements UserAccessQueryPort,DatabaseHealthPort {private final DataSource ds;public JdbcUserAccessQueryAdapter(DataSource ds){this.ds=Objects.requireNonNull(ds);}
 public List<UserOrganizationSummary> organizations(UUID t,UUID o){String sql="SELECT DISTINCT org.organization_id,org.organization_code,org.organization_name FROM app_security.user_plant_access a JOIN core.plant p ON p.plant_id=a.plant_id JOIN core.organization org ON org.organization_id=p.organization_id WHERE a.entra_tenant_id=? AND a.entra_object_id=? AND a.is_active=true AND p.is_active=true AND org.is_active=true ORDER BY org.organization_name";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setObject(1,t);s.setObject(2,o);try(ResultSet r=s.executeQuery()){List<UserOrganizationSummary>x=new ArrayList<>();while(r.next())x.add(new UserOrganizationSummary(r.getLong(1),r.getString(2),r.getString(3)));return List.copyOf(x);}}catch(SQLException e){throw new IllegalStateException("Failed to list user organizations",e);}}
 public List<UserPlantSummary> plants(UUID t,UUID o,long org){String sql="SELECT p.plant_id,p.plant_code,p.plant_name,p.organization_id FROM app_security.user_plant_access a JOIN core.plant p ON p.plant_id=a.plant_id JOIN core.organization org ON org.organization_id=p.organization_id WHERE a.entra_tenant_id=? AND a.entra_object_id=? AND a.is_active=true AND p.is_active=true AND org.is_active=true AND p.organization_id=? ORDER BY p.plant_name";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setObject(1,t);s.setObject(2,o);s.setLong(3,org);try(ResultSet r=s.executeQuery()){List<UserPlantSummary>x=new ArrayList<>();while(r.next())x.add(new UserPlantSummary(r.getLong(1),r.getString(2),r.getString(3),r.getLong(4)));return List.copyOf(x);}}catch(SQLException e){throw new IllegalStateException("Failed to list user plants",e);}}
 public void check(){try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement("SELECT 1 FROM app_security.user_plant_access LIMIT 1")){s.executeQuery();}catch(SQLException e){throw new IllegalStateException("Database health check failed",e);}}
}
